// Update a resource
Resource matrixNode = resourceResolver.getResource("/content/resource1");
ModifiableValueMap mvp = matrixNode.adaptTo(ModifiableValueMap.class);
mvp.put("prop1", "def");
mvp.put("prop2", 33);
